"""Reasoning steps for the 80 hard base questions (H01-H80). See hint_bank_easy.py for the format."""
from hint_bank_easy import H

NO_JOIN = "none needed, every value is in this one table."
AIRLINE_VIA_AIRCRAFT = ("{{flights.aircraft_id}} = {{aircraft.aircraft_id}} and {{aircraft.airline_id}} = "
                        "{{airlines.airline_id}}, a flight reaches its airline through the aircraft.")
TYPE_VIA_AIRCRAFT = ("{{flights.aircraft_id}} = {{aircraft.aircraft_id}} and {{aircraft.type_id}} = "
                     "{{aircraft_types.type_id}}, the limits of the model are on the aircraft type.")
INVOICE_TO_CUSTOMER = ("{{invoices.shipment_id}} = {{shipments.shipment_id}} and {{shipments.customer_id}} = "
                       "{{customers.customer_id}}, an invoice reaches its customer through the shipment.")

HINTS = [
H("H01", "one row per airline: its busiest aircraft.", "airline [[airlines.name]], [[aircraft.tail_number]], completed flights.",
  "'busiest plane' = the aircraft with the most completed flights inside each airline.",
  ["CTE c: completed flights per aircraft from [[flights]] joined to [[aircraft]].",
   "{{flights.aircraft_id}} = {{aircraft.aircraft_id}} in c; at the end {{aircraft.airline_id}} = {{airlines.airline_id}} for the name.",
   "{{flights.status}} = 'completed'; at the end keep rn = 1.",
   "COUNT(*) per aircraft; ROW_NUMBER() OVER (PARTITION BY airline ORDER BY count DESC, [[aircraft.tail_number]]).",
   "ORDER BY airline name.", "rank inside each airline, not over all aircraft; the tail number breaks ties."]),
H("H02", "one row per destination airport: its top airline.", "[[airports.iata_code]], airline [[airlines.name]], completed arrivals.",
  "'top airline per airport' = the airline with the most completed arrivals at each destination.",
  ["CTE c: completed arrivals per destination and airline from [[flights]] joined to [[aircraft]].",
   "{{flights.aircraft_id}} = {{aircraft.aircraft_id}}; then [[airlines]] for the name and [[airports]] on {{flights.destination_airport_id}} for the code.",
   "{{flights.status}} = 'completed'; keep rn = 1.",
   "COUNT(*) per (destination, airline); ROW_NUMBER() OVER (PARTITION BY destination ORDER BY count DESC, airline name).",
   "ORDER BY [[airports.iata_code]].", "arrivals means the destination airport; ties go to the airline name."]),
H("H03", "one row per month with a running total.", "month 'YYYY-MM', invoiced amount, cumulative amount, both rounded to 2 decimals.",
  "'revenue over the year' = monthly SUM([[invoices.amount_usd]]) by [[invoices.issued_date]] in 2025, plus a running total.",
  ["CTE m: [[invoices]] grouped by month of [[invoices.issued_date]].", NO_JOIN,
   "[[invoices.issued_date]] >= '2025-01-01' AND < '2026-01-01'.",
   "substr([[invoices.issued_date]], 1, 7) as month; SUM([[invoices.amount_usd]]); then SUM(invoiced) OVER (ORDER BY month).",
   "ORDER BY month.", "the window sum runs over the monthly rows, round only at the end."]),
H("H04", "one row per month with the change versus the month before.", "month 'YYYY-MM', completed flights, change vs previous month.",
  "'change month to month' = completed flights this month minus the previous month (NULL for the first month).",
  ["CTE m: completed [[flights]] grouped by month of [[flights.actual_departure]].", NO_JOIN, "[[flights.status]] = 'completed'.",
   "COUNT(*) per month; then count - LAG(count) OVER (ORDER BY month).", "ORDER BY month.",
   "group by actual departure, not scheduled; the first month must stay NULL."]),
H("H05", "the 5 aircraft with the shortest average ground time.", "[[aircraft.tail_number]], average ground hours rounded to 1 decimal.",
  "'turnaround' = hours from the arrival of a completed flight to the departure of the same aircraft's next completed flight.",
  ["CTE s: completed [[flights]] with LAG([[flights.actual_arrival]]) per aircraft ordered by [[flights.actual_departure]].",
   "{{flights.aircraft_id}} = {{aircraft.aircraft_id}}, to get the tail number.",
   "[[flights.status]] = 'completed' inside the CTE; prev_arrival IS NOT NULL outside.",
   "AVG((julianday([[flights.actual_departure]]) - julianday(prev_arrival)) * 24) per aircraft.",
   "ORDER BY the average ASC, then tail number; LIMIT 5.",
   "partition the LAG by aircraft; drop each aircraft's first flight, it has no previous arrival."]),
H("H06", "the key accounts above a revenue share.", "customer [[customers.name]], invoiced USD, share in percent, both rounded to 2 decimals.",
  "'key accounts' = customers whose invoiced revenue is more than 4% of all invoiced revenue.",
  ["CTE r: SUM([[invoices.amount_usd]]) per customer.",
   INVOICE_TO_CUSTOMER, "share > 4, where share = 100.0 * revenue / (SELECT SUM([[invoices.amount_usd]]) FROM [[invoices]]).",
   "SUM per customer in the CTE; the total comes from a scalar subquery.", "ORDER BY share DESC.",
   "divide by the total over all invoices, not by the customer's own total; use 100.0."]),
H("H07", "the top 5 rank positions of export airports.", "rank, origin [[airports.iata_code]], tonnes rounded to 1 decimal.",
  "'biggest export airports' = tonnes departing on flown legs per origin airport, ranked with DENSE_RANK.",
  ["CTE t: [[flight_cargo]] legs with status 'flown', weight per origin airport.",
   "{{flight_cargo.flight_id}} = {{flights.flight_id}} for the origin; {{flight_cargo.shipment_id}} = {{shipments.shipment_id}} for the weight; [[airports]] for the code.",
   "[[flight_cargo.leg_status]] = 'flown'; then rank <= 5.",
   "SUM([[shipments.total_weight_kg]]) / 1000.0 per {{flights.origin_airport_id}}; DENSE_RANK() OVER (ORDER BY tonnes DESC).",
   "ORDER BY rank, then [[airports.iata_code]].", "DENSE_RANK keeps ties on the same rank, so more than 5 rows are possible."]),
H("H08", "one row per model: flights loaded above half the volume.", "[[aircraft_types.model]], number of such flights.",
  "'half full' = loaded volume on a completed flight > 50% of the model's [[aircraft_types.max_volume_m3]].",
  ["CTE v: SUM([[shipments.total_volume_m3]]) per flight over [[flight_cargo]].",
   "v to [[flights]] (completed only, in the ON clause), then " + TYPE_VIA_AIRCRAFT,
   "v.m3 > 0.5 * [[aircraft_types.max_volume_m3]].", "GROUP BY model; COUNT(*).", "ORDER BY [[aircraft_types.model]].",
   "sum volume per flight first, then compare; one flight is counted once."]),
H("H09", "a list of aircraft that visited every hub.", "[[aircraft.tail_number]] only.",
  "'been everywhere' = landed (completed flights) at every airport with [[airports.is_cargo_hub]] = 1.",
  ["[[flights]], one row per flight.",
   "{{flights.aircraft_id}} = {{aircraft.aircraft_id}} and {{flights.destination_airport_id}} = {{airports.airport_id}}.",
   "{{flights.status}} = 'completed' AND {{airports.is_cargo_hub}} = 1.",
   "GROUP BY aircraft; HAVING COUNT(DISTINCT airport) = (SELECT COUNT(*) hubs).", "ORDER BY [[aircraft.tail_number]].",
   "this is relational division: count DISTINCT hubs, many flights to one hub must count once."]),
H("H10", "one row per country with a count.", "[[customs_declarations.customs_country]], number of high-tax imports.",
  "'high import taxes' = duty + VAT > 20% of the customs value on import declarations.",
  ["[[customs_declarations]], one row per declaration.", NO_JOIN,
   "[[customs_declarations.declaration_type]] = 'import' AND [[customs_declarations.duty_amount_usd]] + [[customs_declarations.vat_amount_usd]] > 0.2 * [[customs_declarations.customs_value_usd]].",
   "GROUP BY country; COUNT(*).", "ORDER BY count DESC, then country.", "add duty and VAT before comparing; 20% = 0.2."]),
H("H11", "the 3 warehouses with the longest dwell time.", "[[warehouses.warehouse_code]], deliveries, average hours rounded to 2 decimals.",
  "'slow delivery warehouse' = average hours from the RCF scan at that warehouse to the shipment's DLV scan.",
  ["[[tracking_events]] as r, the RCF scans.",
   "the same table again as d ON the same [[tracking_events.shipment_id]] AND d.[[tracking_events.event_code]] = 'DLV'; {{tracking_events.warehouse_id}} = {{warehouses.warehouse_id}} from r.",
   "r.[[tracking_events.event_code]] = 'RCF'.",
   "GROUP BY warehouse; COUNT(*), AVG((julianday(d.[[tracking_events.event_time]]) - julianday(r.[[tracking_events.event_time]])) * 24); HAVING COUNT(*) >= 20.",
   "ORDER BY average DESC, then code; LIMIT 3.", "a self-join on [[tracking_events]]; the warehouse comes from the RCF scan."]),
H("H12", "the 5 origin airports where cargo waits longest.", "origin [[airports.iata_code]], average hours rounded to 2 decimals.",
  "'sits longest before flying' = hours from a shipment's RCS scan to its first DEP scan, per origin airport.",
  ["CTE t: per shipment, MIN([[tracking_events.event_time]]) of RCS and MIN([[tracking_events.event_time]]) of DEP from [[tracking_events]].",
   "t to [[shipments]] on [[shipments.shipment_id]], then {{shipments.origin_airport_id}} = {{airports.airport_id}}.",
   "rcs IS NOT NULL AND dep IS NOT NULL (shipments that departed).",
   "conditional MIN(CASE WHEN ...) per shipment; AVG((julianday(dep) - julianday(rcs)) * 24) per airport.",
   "ORDER BY average DESC, then code; LIMIT 5.", "use the FIRST departure (MIN), a two-leg shipment has two DEP scans."]),
H("H13", "one row per model: its most expensive repair.", "[[aircraft_types.model]], [[maintenance_records.work_order_number]], cost rounded to 2 decimals.",
  "'most expensive repair' = the completed work order with the highest parts + labour cost per model.",
  ["CTE m: completed [[maintenance_records]] with model and cost.",
   "{{maintenance_records.aircraft_id}} = {{aircraft.aircraft_id}} and {{aircraft.type_id}} = {{aircraft_types.type_id}}.",
   "[[maintenance_records.status]] = 'completed'; keep rn = 1.",
   "cost = parts + labour; ROW_NUMBER() OVER (PARTITION BY model ORDER BY cost DESC, work order number).",
   "ORDER BY [[aircraft_types.model]].", "rank per model, not per aircraft; work order number breaks ties."]),
H("H14", "one row per airline with a late percentage.", "airline [[airlines.name]], completed flights, late departure percent rounded to 1 decimal.",
  "'late most often' = share of completed flights departing more than 15 minutes after schedule.",
  ["[[flights]], one row per flight.", AIRLINE_VIA_AIRCRAFT, "{{flights.status}} = 'completed'.",
   "COUNT(*); 100.0 * SUM(CASE WHEN (julianday([[flights.actual_departure]]) - julianday([[flights.scheduled_departure]])) * 1440 > 15 THEN 1 ELSE 0 END) / COUNT(*).",
   "ORDER BY percent DESC, then airline name.", "more than 15 means > 15, not >= 15; minutes = day difference * 1440."]),
H("H15", "one row per loyalty tier.", "[[customers.loyalty_tier]], average discount percent rounded to 2 decimals.",
  "'discount' = [[invoices.discount_usd]] as a percent of the price before discount (amount + discount), averaged per invoice.",
  ["[[invoices]], one row per invoice.", INVOICE_TO_CUSTOMER, "none, all invoices.",
   "AVG(100.0 * discount / (amount + discount)) per tier.", "ORDER BY [[customers.loyalty_tier]].",
   "the base is amount + discount, because [[invoices.amount_usd]] is already after the discount."]),
H("H16", "one row per aircraft with heavy takeoffs.", "[[aircraft.tail_number]], number of heavy takeoffs.",
  "'heavy takeoff' = [[flights.takeoff_weight_kg]] > 95% of the model's [[aircraft_types.max_takeoff_weight_kg]].",
  ["[[flights]], one row per flight.", TYPE_VIA_AIRCRAFT,
   "[[flights.takeoff_weight_kg]] > 0.95 * [[aircraft_types.max_takeoff_weight_kg]].", "GROUP BY aircraft; COUNT(*).",
   "ORDER BY count DESC, then tail number.",
   "no status filter is written, because takeoff weight is only filled for completed flights; NULLs fail the comparison."]),
H("H17", "one row per currency with two averages.", "[[payments.original_currency]], average rate H1, average rate H2, rounded to 6 decimals.",
  "'first vs second half' = payments dated January-June 2025 vs July-December 2025; non-USD currencies only.",
  ["[[payments]], one row per payment.", NO_JOIN,
   "[[payments.original_currency]] <> 'USD' AND [[payments.payment_date]] >= '2025-01-01'.",
   "AVG(CASE WHEN date < '2025-07-01' THEN rate END) and AVG(CASE WHEN date >= '2025-07-01' THEN rate END).",
   "ORDER BY currency.", "CASE without ELSE gives NULL, and AVG skips NULLs, so each half is averaged on its own rows."]),
H("H18", "one row per connecting airport.", "connecting [[airports.iata_code]], number of long connections.",
  "'long layover' = more than 48 hours between leg 1 actual arrival and leg 2 actual departure, both legs completed.",
  ["[[flight_cargo]] as l1 (leg 1).",
   "l2 = [[flight_cargo]] of the same shipment with leg 2; f1, f2 = [[flights]] of each leg; [[airports]] on f1's destination.",
   "l1 leg 1; f1 and f2 completed; (julianday(f2.[[flights.actual_departure]]) - julianday(f1.[[flights.actual_arrival]])) * 24 > 48.",
   "GROUP BY connecting airport; COUNT(*).", "ORDER BY count DESC, then code.",
   "the connecting airport is leg 1's destination; join [[flights]] twice with different aliases."]),
H("H19", "one row per insurer.", "[[insurance_claims.insurer_name]], paid claims, average days to settle rounded to 1 decimal.",
  "'quick' = average days from [[insurance_claims.filed_date]] to [[insurance_claims.settlement_date]] on paid claims.",
  ["[[insurance_claims]], one row per claim.", NO_JOIN, "[[insurance_claims.status]] = 'paid'.",
   "GROUP BY insurer; COUNT(*), AVG(julianday([[insurance_claims.settlement_date]]) - julianday([[insurance_claims.filed_date]])).",
   "ORDER BY average ASC (quickest first), then insurer.", "only paid claims have a settlement date."]),
H("H20", "captain and first officer pairs.", "captain [[crew_members.employee_number]], first officer [[crew_members.employee_number]], flights together.",
  "'always fly together' = captain and first officer on the same completed flight at least 10 times.",
  ["[[crew_assignments]] as c, the captain rows.",
   "fo = [[crew_assignments]] on the same {{crew_assignments.flight_id}} with role 'first_officer'; [[crew_members]] twice for both employee numbers.",
   "c.[[crew_assignments.duty_role]] = 'captain' AND c.[[crew_assignments.assignment_status]] = 'completed'.",
   "GROUP BY captain number, first officer number; COUNT(*); HAVING COUNT(*) >= 10.",
   "ORDER BY count DESC, captain, first officer.", "self-join on [[crew_assignments]]; join [[crew_members]] twice with different aliases."]),
H("H21", "the airports that grew from Q3 to Q4.", "origin [[airports.iata_code]], Q3 departures, Q4 departures.",
  "'grew lately' = more completed departures in Q4 2025 than in Q3 2025, by [[flights.actual_departure]].",
  ["[[flights]], one row per flight.", "{{flights.origin_airport_id}} = {{airports.airport_id}}, to get the code.",
   "{{flights.status}} = 'completed'.",
   "two conditional SUMs (CASE WHEN date in Q3/Q4 THEN 1 ELSE 0 END); HAVING q4 > q3.", "ORDER BY [[airports.iata_code]].",
   "use half-open quarter ranges; compare in HAVING, after grouping."]),
H("H22", "customers with open invoices and no recent payment.", "customer [[customers.name]], number of open invoices.",
  "'stopped paying' = no payment in the 60 days before 2025-12-20; open = invoice status 'unpaid' or 'partially_paid'.",
  ["[[invoices]], one row per invoice.", INVOICE_TO_CUSTOMER,
   "[[invoices.status]] IN ('unpaid', 'partially_paid') AND NOT EXISTS (a [[payments]] row for the customer with [[payments.payment_date]] >= date('2025-12-20', '-60 days')).",
   "GROUP BY customer; COUNT(*).", "ORDER BY count DESC, then {{customers.customer_id}}.",
   "the 'now' date is 2025-12-20 from the dataset, not today's date; link payments by {{payments.customer_id}}."]),
H("H23", "one row per model.", "[[aircraft_types.model]], number of mixed-risk flights.",
  "'mixed risky cargo' = a flight carrying at least one dangerous-goods AND at least one temperature-controlled shipment.",
  ["[[flights]], one row per flight (any status).", TYPE_VIA_AIRCRAFT,
   "EXISTS (a leg on this flight with [[shipments.is_dangerous_goods]] = 1) AND EXISTS (a leg with [[shipments.is_temperature_controlled]] = 1).",
   "GROUP BY model; COUNT(*).", "ORDER BY [[aircraft_types.model]].",
   "two separate EXISTS; the two conditions may be met by different shipments. Joining legs would count a flight many times."]),
H("H24", "one row per commodity.", "[[shipments.commodity_category]], number of shipments in the heaviest quarter.",
  "'heavy shipments' = the top quartile of all shipments by [[shipments.total_weight_kg]] (NTILE(4)).",
  ["CTE q: [[shipments]] with NTILE(4) OVER (ORDER BY weight, id).", NO_JOIN, "quartile = 4.",
   "GROUP BY [[shipments.commodity_category]]; COUNT(*).", "ORDER BY count DESC, then category.",
   "NTILE over ALL shipments, not per category; {{shipments.shipment_id}} breaks weight ties."]),
H("H25", "the 5 customers who book most often.", "customer [[customers.name]], shipments, average days between bookings rounded to 2 decimals.",
  "'frequent' = (last [[shipments.booking_date]] - first) / (shipments - 1), customers with at least 20 non-cancelled shipments.",
  ["[[customers]], one row per customer.", "{{shipments.customer_id}} = {{customers.customer_id}}.",
   "{{shipments.status}} <> 'cancelled'.", "GROUP BY customer; COUNT(*), (julianday(MAX) - julianday(MIN)) / (COUNT(*) - 1); HAVING COUNT(*) >= 20.",
   "ORDER BY average ASC, then {{customers.customer_id}}; LIMIT 5.", "n bookings have n - 1 gaps, divide by COUNT(*) - 1."]),
H("H26", "the crew above 40 November hours.", "[[crew_members.employee_number]], block hours rounded to 1 decimal.",
  "'flew a lot in November' = more than 40 credited block hours on completed assignments reporting in November 2025.",
  ["[[crew_assignments]], one row per duty.", "{{crew_assignments.crew_member_id}} = {{crew_members.crew_member_id}}, for the employee number.",
   "[[crew_assignments.assignment_status]] = 'completed' AND [[crew_assignments.report_time]] in November 2025.",
   "SUM([[crew_assignments.block_minutes_credited]]) / 60.0 per person; HAVING > 40.", "ORDER BY hours DESC, then employee number.",
   "minutes to hours with / 60.0; the threshold is in HAVING."]),
H("H27", "one row per loyalty tier.", "[[customers.loyalty_tier]], delivered shipments, on-time percent rounded to 1 decimal.",
  "'delivered on time' = DLV scan date <= [[shipments.requested_delivery_date]]; 'good customers' = loyalty tiers.",
  ["[[shipments]], one row per shipment.",
   "[[tracking_events]] ON same shipment AND [[tracking_events.event_code]] = 'DLV'; {{shipments.customer_id}} = {{customers.customer_id}}.",
   "only shipments with a DLV scan (inner join).",
   "COUNT(*); 100.0 * SUM(CASE WHEN substr([[tracking_events.event_time]], 1, 10) <= [[shipments.requested_delivery_date]] THEN 1 ELSE 0 END) / COUNT(*).",
   "ORDER BY [[customers.loyalty_tier]].", "compare dates only (first 10 characters), the scan time has hours."]),
H("H28", "one row per booking month.", "month 'YYYY-MM', bookings, express share in percent rounded to 1 decimal.",
  "'express trend' = share of shipments with [[shipments.service_level]] = 'express' per booking month, cancelled included.",
  ["[[shipments]], one row per booking.", NO_JOIN, "none, cancelled bookings count too.",
   "substr([[shipments.booking_date]], 1, 7); COUNT(*); 100.0 * SUM(CASE WHEN express THEN 1 ELSE 0 END) / COUNT(*).",
   "ORDER BY month.", "do not filter express in WHERE, the share needs all bookings."]),
H("H29", "aircraft above their airline's average.", "airline [[airlines.name]], [[aircraft.tail_number]], block hours rounded to 1 decimal.",
  "'overworked' = completed block hours above the average of the flying aircraft of the same airline.",
  ["CTE h: completed block hours per aircraft; CTE avg_h: AVG(hours) per airline.",
   "{{flights.aircraft_id}} = {{aircraft.aircraft_id}} in h; h to avg_h on airline; {{aircraft.airline_id}} = {{airlines.airline_id}} for the name.",
   "[[flights.status]] = 'completed'; h.hours > avg_h.avg_hours.",
   "SUM((julianday([[flights.actual_arrival]]) - julianday([[flights.actual_departure]])) * 24) per aircraft, then AVG per airline.",
   "ORDER BY airline name, hours DESC.", "compare with the airline's own average, not the whole fleet's."]),
H("H30", "the 5 fullest routes.", "origin and destination [[airports.iata_code]], flights, average load factor rounded to 1 decimal.",
  "'fullest' = average of (cargo kg on the flight / [[aircraft_types.max_payload_kg]] * 100) over completed flights with cargo.",
  ["CTE l: SUM([[shipments.total_weight_kg]]) per flight over [[flight_cargo]].",
   "l to completed [[flights]]; " + TYPE_VIA_AIRCRAFT + " [[airports]] twice for origin and destination.",
   "completed flights only (in the ON clause); routes with at least 10 flights (HAVING).",
   "per flight kg * 100.0 / max payload, then AVG per route.", "ORDER BY load factor DESC, origin, destination; LIMIT 5.",
   "sum kg per flight before dividing; use two aliases for [[airports]]."]),
H("H31", "customers with many incidents.", "customer [[customers.name]], incidents, approved claim amount rounded to 2 decimals.",
  "'lots of problems' = at least 4 incidents on their shipments; approved amount from approved or paid claims, 0 if none.",
  ["[[incidents]], one row per incident.",
   "{{incidents.flight_cargo_id}} = {{flight_cargo.flight_cargo_id}}, then [[shipments]] and [[customers]]; LEFT JOIN [[insurance_claims]] on {{insurance_claims.incident_id}}.",
   "none in WHERE; the claim status is checked inside the CASE.",
   "COUNT(*); COALESCE(SUM(CASE WHEN claim status IN ('approved','paid') THEN [[insurance_claims.approved_amount_usd]] END), 0); HAVING COUNT(*) >= 4.",
   "ORDER BY incidents DESC, then {{customers.customer_id}}.",
   "LEFT JOIN keeps incidents without a claim; COALESCE turns no claims into 0."]),
H("H32", "one row per airline with knock-on delays.", "airline [[airlines.name]], number of knock-on delays.",
  "'delays spreading' = a completed flight departing > 60 min late whose aircraft's previous completed flight arrived > 60 min late.",
  ["CTE s: completed [[flights]] with departure delay and LAG(arrival delay) per aircraft by [[flights.actual_departure]].",
   AIRLINE_VIA_AIRCRAFT, "[[flights.status]] = 'completed' in the CTE; dep_delay > 60 AND prev_arr_delay > 60.",
   "delays in minutes = day difference * 1440; COUNT(*) per airline.", "ORDER BY count DESC, then airline name.",
   "the LAG must be partitioned by aircraft, the previous flight is the same plane's."]),
H("H33", "customers that shipped to every hub.", "[[customers.customer_id]], [[customers.name]].",
  "'everywhere' = non-cancelled shipments to every airport with [[airports.is_cargo_hub]] = 1 as destination.",
  ["[[customers]], one row per customer.",
   "{{shipments.customer_id}} = {{customers.customer_id}} and {{shipments.destination_airport_id}} = {{airports.airport_id}}.",
   "{{shipments.status}} <> 'cancelled' AND {{airports.is_cargo_hub}} = 1.",
   "GROUP BY customer; HAVING COUNT(DISTINCT airport) = (SELECT COUNT(*) hubs).", "ORDER BY {{customers.customer_id}}.",
   "relational division: count DISTINCT hubs."]),
H("H34", "the 5 active aircraft longest without maintenance.", "[[aircraft.tail_number]], last maintenance end, days since (integer).",
  "'due for maintenance' = most days from the end of the latest completed maintenance to 2025-12-20, active aircraft.",
  ["[[aircraft]], one row per airframe.", "{{maintenance_records.aircraft_id}} = {{aircraft.aircraft_id}}.",
   "{{aircraft.status}} = 'active' AND {{maintenance_records.status}} = 'completed'.",
   "MAX([[maintenance_records.end_time]]); CAST(julianday('2025-12-20') - julianday(MAX([[maintenance_records.end_time]])) AS INTEGER).",
   "ORDER BY days DESC, then tail number; LIMIT 5.", "use the dataset date 2025-12-20, not today; the latest end time is MAX."]),
H("H35", "the 5 most expensive fuel airports.", "[[airports.iata_code]], average price, difference from the network average, rounded to 4.",
  "'expensive fuel places' = highest AVG([[fuel_uplifts.price_usd_per_litre]]) per airport.",
  ["CTE p: AVG price per {{fuel_uplifts.airport_id}}.", "p to [[airports]] for the code.", "none.",
   "difference = airport average - (SELECT AVG(price) FROM [[fuel_uplifts]]).", "ORDER BY average DESC, then code; LIMIT 5.",
   "the network average is over all uplifts, not the average of airport averages."]),
H("H36", "the 5 crew members with the longest rest.", "[[crew_members.employee_number]], [[crew_members.crew_rank]], longest rest in hours rounded to 1.",
  "'longest break' = MAX([[crew_assignments.rest_minutes_before]]) / 60 per crew member.",
  ["[[crew_assignments]], one row per duty.", "{{crew_assignments.crew_member_id}} = {{crew_members.crew_member_id}}.",
   "none.", "GROUP BY crew member; MAX(rest minutes) / 60.0.", "ORDER BY MAX(rest) DESC, then employee number; LIMIT 5.",
   "MAX skips duties without a rest value (NULL), which is fine."]),
H("H37", "one row per origin airport.", "origin [[airports.iata_code]], number of last-minute clearances.",
  "'last-minute customs' = export cleared less than 2 hours before the leg-1 actual departure.",
  ["[[customs_declarations]], one row per declaration.",
   "{{flight_cargo.shipment_id}} = {{customs_declarations.shipment_id}} with leg 1; [[flights]] on {{flight_cargo.flight_id}}; [[airports]] on {{flights.origin_airport_id}}.",
   "export, cleared, flight completed, (julianday([[flights.actual_departure]]) - julianday([[customs_declarations.cleared_at]])) * 24 < 2.",
   "GROUP BY airport; COUNT(*).", "ORDER BY count DESC, then code.", "only leg 1, the export happens before the first flight."]),
H("H38", "one row per commodity with a cumulative share.", "[[shipments.commodity_category]], declared value, cumulative share in percent, rounded to 2.",
  "'matters most by value' = categories ordered by declared value of non-cancelled shipments, with a running share (Pareto).",
  ["CTE v: SUM([[shipments.declared_value_usd]]) per category.", NO_JOIN, "{{shipments.status}} <> 'cancelled'.",
   "100.0 * SUM(value) OVER (ORDER BY value DESC) / SUM(value) OVER ().", "ORDER BY value DESC.",
   "the running sum and the total are both window sums over the CTE rows."]),
H("H39", "one row per big customer: their top destination.", "customer [[customers.name]], top destination [[airports.iata_code]], shipments to it.",
  "'favourite destination' = most frequent destination of non-cancelled shipments, customers with at least 60 of them.",
  ["CTE c: non-cancelled [[shipments]] per customer and destination.",
   "{{shipments.destination_airport_id}} = {{airports.airport_id}} in c; [[customers]] at the end for the name.",
   "{{shipments.status}} <> 'cancelled'; rn = 1 AND total >= 60.",
   "COUNT(*) per pair; ROW_NUMBER() by count DESC, code; SUM(n) OVER (PARTITION BY customer) as total.",
   "ORDER BY {{customers.customer_id}}.", "the 60 threshold is on the customer's total, not on the top destination's count."]),
H("H40", "one row per customer type.", "[[customers.customer_type]], two-part invoices, average days between payments rounded to 1.",
  "'instalment gaps' = invoices paid in exactly two payments; days from the first to the second payment.",
  ["CTE two: [[payments]] per invoice with MIN and MAX [[payments.payment_date]], HAVING COUNT(*) = 2.",
   "two to [[invoices]] on {{invoices.invoice_id}}, then " + INVOICE_TO_CUSTOMER, "exactly two payments (in the CTE).",
   "AVG(julianday(second) - julianday(first)) per type; COUNT(*).", "ORDER BY [[customers.customer_type]].",
   "exactly two, not two or more; use the type from [[customers]]."]),
]

